const SYSTEM="XRAY_NASDAQ_PERSONAL";
const keys=["asof","source_run","run_status","scan_count","sheet_asof","sheet_exact","guardian","score","identity_verified"];
const iso=x=>typeof x==="string"&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(Date.parse(x+"T00:00:00Z"))&&new Date(x+"T00:00:00Z").toISOString().slice(0,10)===x;
function classify(o,seen){
 const out=(status,reason,event_key=null)=>({system:SYSTEM,status,reason,event_key,may_notify:false,may_dispatch:false,may_trade:false,source_authentication:"CALLER_WITNESS_NOT_ATTESTED"});
 if(!o||!iso(o.expected_asof)||!Array.isArray(seen))return out("UNKNOWN","INVALID_INPUT");
 if(keys.some(k=>o[k]===null||o[k]===undefined))return out("UNKNOWN","MISSING_WITNESS");
 if(!iso(o.asof)||!iso(o.sheet_asof)||typeof o.source_run!=="string"||!(/^[1-9][0-9]{0,20}$/.test(o.source_run)))return out("UNKNOWN","INVALID_WITNESS");
 if(o.asof!==o.expected_asof)return out("HOLD","SOURCE_ASOF_MISMATCH");
 if(["queued","in_progress","waiting","pending"].includes(o.run_status))return out("WAIT","RUN_NOT_TERMINAL");
 if(o.run_status!=="success")return out("HOLD","RUN_NOT_SUCCESS");
 if(o.scan_count!==477||o.sheet_asof!==o.expected_asof||[o.sheet_exact,o.guardian,o.score,o.identity_verified].some(v=>v!==true))return out("HOLD","ACCEPTANCE_WITNESS_MISMATCH");
 const key=SYSTEM+"|EOD_ACCEPTED|"+o.expected_asof;
 return out(seen.includes(key)?"DUPLICATE":"ACCEPTED","READ_ONLY_CANDIDATE",key);
}

const observation={"asof":"2026-11-10","expected_asof":"2026-11-10","source_run":"123","run_status":"success","scan_count":477,"sheet_asof":"2026-11-10","sheet_exact":true,"guardian":true,"score":true,"identity_verified":true};
return [{json:{...classify(observation,[]),fixture_only:true}}];
